    # Check if reversing any suffix makes the string lexicographically smaller
    for i in range(1, n):
        suffix = s[n-i:]
        reversed_suffix = suffix[::-1]
        if reversed_suffix < s:
            return 'YES', n-i+1, n
    # Check if reversing any prefix makes the string lexicographically smaller
    for i in range(1, n-1):
        prefix = s[:i]
        reversed_prefix = prefix[::-1]
        if reversed_prefix < s:
            return 'YES', 1, i
    # Check if reversing any substring in between makes the string lexicographically smaller
    for i in range(1, n-2):
