def can_reverse_to_smaller(s):
    n = len(s)

    # Check if reversing any suffix can make the string smaller
    for i in range(n-1, 0, -1):
        if s[i] < s[i-1]:
            return True, i, i

    # Check if reversing any prefix can make the string smaller
    for i in range(1, n):
        if s[i] < s[i-1]:
            return True, 1, i

    # Check if reversing any substring in between can make the string smaller
    for i in range(1, n-1):
        for j in range(i+1, n):
            if s[j] < s[i-1] and s[j-1] >= s[i-1]:
                return True, i, j

    return False, None, None

