def find_substring_to_reverse(s):
    n = len(s)
    for i in range(n-1):
        for j in range(i+1, n):
            reversed_part = s[i:j][::-1]
            new_string = s[:i] + reversed_part + s[j:]
            if new_string < s:
                return "YES", i+1, j
    return "NO"

