def find_reversible_substring(s):
    n = len(s)
    for i in range(n-1, 0, -1):
        if s[i] < s[i-1]:
            for j in range(i+1, n):
                if s[j] >= s[j-1]:
                    return "YES", i, j
            return "NO"
    return "NO"

